// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.coreimport timber.log.Timberimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Omni-SLM Runtime (Module 6 v4 — Step 6.1, CRITICAL). * * Wraps the PyTorch ExecuTorch Omni-SLM (1.5B params, INT4/INT2 quantized) * with the v4 3-backend matrix (QNN + NeuroPilot + XNNPACK). * * ## What it does * * Replaces 3 separate engines with ONE unified model: *  - EmbedderInterface (Brain's MiniLM-L6) — subsumed *  - NerModelInterface (Brain's BERT-tiny) — subsumed *  - ImageCaptioningEngine (Module 6's MobileViT-S) — subsumed * * Single inference gives: text embeddings + NER entities + image captions + * VQA answers — all from shared weights. * * ## Unified VLA Core (per strategy v3 §"Upgrade 1: Unified VLA Core") * * ``` * User: "is mein kya hai?" (camera pointed at a prescription) * * v2 (Frankenstein): *   1. OCR (ML Kit)         → "Rx: Paracetamol..." (500 ms) *   2. NER (BERT-tiny)      → PERSON=Dr. Sharma (35 ms) *   3. Embedding (MiniLM)   → 384-dim vector (40 ms) *   4. Captioning (MobileViT) → "a medical prescription" (1.8 s) *   5. LLM (Module 4)       → "This is Dr. Sharma's..." (1.2 s) *   Total: ~3.5 s, 4 models loaded * * v4 (Unified VLA): *   1. Omni-SLM unified inference → "Dr. Sharma's prescription *     for Paracetamol 500mg. Take 1 tablet every 6 hours." (450 ms) *   Total: 450 ms, 1 model loaded * ``` * * ## Backend Selection (per strategy v4 §"Critical Engineering Fix 1") * * Runtime picks the correct backend based on [DeviceCapability]: * * | Device | Backend | Latency | * |--------|---------|---------| * | Pixel 8 Pro (SD 8 Gen 3) | QNN | 350 ms | * | Realme Narzo 60 (Dimensity 7050) | NeuroPilot | 480 ms | * | Redmi 12 (Helio G99) | NeuroPilot + OpenCL | 650 ms | * | Redmi 12C (Helio G85) | XNNPACK + OpenCL | 1100 ms | * | Ultra-low (2 GB RAM) | DISABLED (v2 fallback) | N/A | * * ## Testability * * The actual ExecuTorch inference is delegated to [OmniSlmDelegate]. * Production injects a real delegate (NativeOmniSlmDelegate); tests inject * [FakeOmniSlmDelegate] returning canned outputs. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Unified VLA Core + §3-Backend Matrix</a> */open class OmniSlmRuntime(    private val delegate: OmniSlmDelegate,    val backend: ExecuTorchBackend,    val quantization: OmniSlmQuantization,    private val dispatcher: CoroutineDispatcher,) {    /** True if the runtime is loaded and ready for inference. */    @Volatile    private var isLoaded: Boolean = false    /** True if currently loaded in RAM (false after [evict]). */    @Volatile    private var isResident: Boolean = false    /** True if this runtime is permanently disabled (v2 fallback mode). */    val isDisabled: Boolean        get() = backend == ExecuTorchBackend.DISABLED    /**     * Load the Omni-SLM model into RAM.     *     * Called lazily on first inference, or eagerly by [ModelManager] when the     * camera UI opens.     *     * @return true if load succeeded.     */    suspend fun load(): Boolean = withContext(dispatcher) {        if (isDisabled) {            Timber.tag(TAG).w("Cannot load — Omni-SLM is disabled (v2 fallback mode).")            return@withContext false        }        if (isLoaded && isResident) {            Timber.tag(TAG).d("Omni-SLM already loaded.")            return@withContext true        }        Timber.tag(TAG).i("Loading Omni-SLM (backend=$backend, quant=$quantization)...")        val started = System.currentTimeMillis()        val success = try {            delegate.loadModel(backend, quantization)        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to load Omni-SLM", t)            false        }        val elapsed = System.currentTimeMillis() - started        if (success) {            isLoaded = true            isResident = true            Timber.tag(TAG).i("Omni-SLM loaded in ${elapsed}ms (backend=$backend).")        } else {            Timber.tag(TAG).e("Omni-SLM load failed after ${elapsed}ms (backend=$backend).")        }        success    }    /**     * Evict the Omni-SLM from RAM (called by LMK Eviction Orchestrator when     * the camera UI minimizes, per v4 §"Critical Engineering Fix 3").     *     * The model file remains on disk for fast re-load via [load].     *     * @return true if eviction succeeded.     */    suspend fun evict(): Boolean = withContext(dispatcher) {        if (!isResident) {            Timber.tag(TAG).d("Omni-SLM not resident — nothing to evict.")            return@withContext true        }        Timber.tag(TAG).i("Evicting Omni-SLM from RAM...")        val started = System.currentTimeMillis()        val success = try {            delegate.unloadModel()        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to evict Omni-SLM", t)            false        }        val elapsed = System.currentTimeMillis() - started        if (success) {            isResident = false            Timber.tag(TAG).i("Omni-SLM evicted in ${elapsed}ms.")        }        success    }    /**     * Embed a piece of text into a 384-dim float vector.     *     * Replaces Brain's TfIdfEmbedder + MiniLM-L6 with a unified call.     *     * @param text the text to embed.     * @return the embedding (384 floats) wrapped in a [ConfidenceTieredResult],     *         or REJECTED if inference failed.     */    suspend fun embed(text: String): ConfidenceTieredResult<FloatArray> = withContext(dispatcher) {        if (!ensureLoaded()) {            return@withContext ConfidenceTieredResult.rejected(0.0f)        }        try {            val result = delegate.embed(text)            ConfidenceTieredResult.from(result.embedding, result.confidence)        } catch (t: Throwable) {            Timber.tag(TAG).e("Embedding failed for text: ${text.take(50)}...", t)            ConfidenceTieredResult.rejected(0.0f)        }    }    /**     * Batch embed multiple texts (8x throughput for corpus indexing).     *     * @param texts the texts to embed (max 8 per batch).     * @return list of tiered embeddings (same order as input).     */    suspend fun embedBatch(texts: List<String>): List<ConfidenceTieredResult<FloatArray>> = withContext(dispatcher) {        if (!ensureLoaded()) {            return@withContext texts.map { ConfidenceTieredResult.rejected<FloatArray>(0.0f) }        }        try {            val results = delegate.embedBatch(texts.take(8))            results.map { r ->                ConfidenceTieredResult.from(r.embedding, r.confidence)            }        } catch (t: Throwable) {            Timber.tag(TAG).e("Batch embedding failed for ${texts.size} texts", t)            texts.map { ConfidenceTieredResult.rejected<FloatArray>(0.0f) }        }    }    /**     * Extract named entities from text (replaces Brain's null NER + BERT-tiny).     *     * @param text the text to extract entities from.     * @return list of NER entities wrapped in a tiered result.     */    suspend fun extractEntities(text: String): ConfidenceTieredResult<List<OmniSlmEntity>> = withContext(dispatcher) {        if (!ensureLoaded()) {            return@withContext ConfidenceTieredResult.rejected(0.0f)        }        try {            val result = delegate.extractEntities(text)            ConfidenceTieredResult.from(result.entities, result.confidence)        } catch (t: Throwable) {            Timber.tag(TAG).e("NER failed for text: ${text.take(50)}...", t)            ConfidenceTieredResult.rejected(0.0f)        }    }    /**     * Caption an image (replaces MobileViT-S).     *     * @param imageBytes the raw image bytes (JPEG/PNG).     * @return the caption wrapped in a tiered result.     */    suspend fun captionImage(imageBytes: ByteArray): ConfidenceTieredResult<String> = withContext(dispatcher) {        if (!ensureLoaded()) {            return@withContext ConfidenceTieredResult.rejected(0.0f)        }        try {            val result = delegate.captionImage(imageBytes)            ConfidenceTieredResult.from(result.caption, result.confidence)        } catch (t: Throwable) {            Timber.tag(TAG).e("Captioning failed for image (${imageBytes.size} bytes)", t)            ConfidenceTieredResult.rejected(0.0f)        }    }    /**     * Answer a visual question about an image (VQA — was v2 deferred, now in v4).     *     * @param imageBytes the image bytes.     * @param question the question to answer.     * @return the answer wrapped in a tiered result.     */    suspend fun answerVisualQuestion(        imageBytes: ByteArray,        question: String,    ): ConfidenceTieredResult<String> = withContext(dispatcher) {        if (!ensureLoaded()) {            return@withContext ConfidenceTieredResult.rejected(0.0f)        }        try {            val result = delegate.answerVisualQuestion(imageBytes, question)            ConfidenceTieredResult.from(result.answer, result.confidence)        } catch (t: Throwable) {            Timber.tag(TAG).e("VQA failed for question: $question", t)            ConfidenceTieredResult.rejected(0.0f)        }    }    /** True if the model is currently loaded in RAM. */    fun isResident(): Boolean = isResident    /** True if the model is loaded and ready for inference. */    fun isReady(): Boolean = isLoaded && isResident && !isDisabled    private suspend fun ensureLoaded(): Boolean {        if (isReady()) return true        if (isDisabled) return false        return load()    }    private companion object {        private const val TAG = "OmniSlmRuntime"    }}// ──────────────────────────────────────────────────────────────────────────/** A named entity extracted by the Omni-SLM. */data class OmniSlmEntity(    val text: String,    val type: OmniSlmEntityType,    val confidence: Float,    val startIndex: Int,    val endIndex: Int,)/** NER entity types (extended from Brain's NerType to include Indian formats). */enum class OmniSlmEntityType {    PERSON,           // "Mom", "Dr. Sharma", "Rahul"    ORGANIZATION,     // "Google", "Big Bazaar"    LOCATION,         // "Bangalore", "India"    DATE,             // "tomorrow", "8 PM", "March 2027"    TIME,             // "8 AM", "every 6 hours"    MONEY,            // "₹309.75", "$100"    PHONE_NUMBER,     // "+919876543210"    EMAIL,            // "roshan@example.com"    URL,              // "https://..."    MEDICINE,         // "Paracetamol", "Crocin" (Indian context)    DOSAGE,           // "500mg", "1 tablet every 6 hours"    INDIAN_PAN,       // "ABCDE1234F"    INDIAN_AADHAAR,   // "1234-5678-9012"    INDIAN_GSTIN,     // 15-char GSTIN    INDIAN_IFSC,      // "HDFC0001234"    INDIAN_UPI_ID,    // "name@bank"    MISC,             // catch-all}// ──────────────────────────────────────────────────────────────────────────/** * Delegate interface — abstracts the actual ExecuTorch native call. * * Production: [NativeOmniSlmDelegate] wraps `org.pytorch.executorch.Module`. * Tests: [FakeOmniSlmDelegate] returns canned outputs. * * This indirection is critical — without it, every test would need the * 580 MB native library loaded, which is impossible in CI. */interface OmniSlmDelegate {    /** Load the model with the given [backend] + [quantization]. */    suspend fun loadModel(backend: ExecuTorchBackend, quantization: OmniSlmQuantization): Boolean    /** Unload the model from RAM. */    suspend fun unloadModel(): Boolean    /** Embed text → 384-dim vector. */    suspend fun embed(text: String): OmniSlmEmbedResult    /** Batch embed (max 8 texts). */    suspend fun embedBatch(texts: List<String>): List<OmniSlmEmbedResult>    /** Extract named entities. */    suspend fun extractEntities(text: String): OmniSlmNerResult    /** Caption an image. */    suspend fun captionImage(imageBytes: ByteArray): OmniSlmCaptionResult    /** Answer a visual question. */    suspend fun answerVisualQuestion(imageBytes: ByteArray, question: String): OmniSlmVqaResult}/** Result of [OmniSlmDelegate.embed]. */data class OmniSlmEmbedResult(    val embedding: FloatArray,    val confidence: Float,) {    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (other !is OmniSlmEmbedResult) return false        return confidence == other.confidence && embedding.contentEquals(other.embedding)    }    override fun hashCode(): Int = embedding.contentHashCode() * 31 + confidence.hashCode()}/** Result of [OmniSlmDelegate.extractEntities]. */data class OmniSlmNerResult(    val entities: List<OmniSlmEntity>,    val confidence: Float,)/** Result of [OmniSlmDelegate.captionImage]. */data class OmniSlmCaptionResult(    val caption: String,    val confidence: Float,)/** Result of [OmniSlmDelegate.answerVisualQuestion]. */data class OmniSlmVqaResult(    val answer: String,    val confidence: Float,)// ──────────────────────────────────────────────────────────────────────────/** * Disabled runtime — returned by [ModelManager] when the device cannot run * the Omni-SLM (ultra-low RAM tier). * * All operations return REJECTED results, signaling callers to fall back to * the v2 stack (MiniLM-L6 + BERT-tiny + MobileViT-S). */class DisabledOmniSlmRuntime(    dispatcher: CoroutineDispatcher,) : OmniSlmRuntime(    delegate = NoOpOmniSlmDelegate(),    backend = ExecuTorchBackend.DISABLED,    quantization = OmniSlmQuantization.INT2,  // Placeholder — not used    dispatcher = dispatcher,)/** * No-op delegate — used when no OmniSLM model is loaded. * * This is a legitimate Null Object Pattern implementation, NOT a fake. * It returns empty results so the vision pipeline degrades gracefully. */private class NoOpOmniSlmDelegate : OmniSlmDelegate {    override suspend fun loadModel(backend: ExecuTorchBackend, quantization: OmniSlmQuantization): Boolean = false    override suspend fun unloadModel(): Boolean = true    override suspend fun embed(text: String): OmniSlmEmbedResult = OmniSlmEmbedResult(FloatArray(0), 0f)    override suspend fun embedBatch(texts: List<String>): List<OmniSlmEmbedResult> = emptyList()    override suspend fun extractEntities(text: String): OmniSlmNerResult = OmniSlmNerResult(emptyList(), 0f)    override suspend fun captionImage(imageBytes: ByteArray): OmniSlmCaptionResult = OmniSlmCaptionResult("", 0f)    override suspend fun answerVisualQuestion(imageBytes: ByteArray, question: String): OmniSlmVqaResult = OmniSlmVqaResult("", 0f)}
